export const PLAN_KINDS={subscription:'Plano principal de criação',publishing:'Publicação assistida',consulting:'Consultoria avulsa',ad_management:'Gestão de impulsionamento',prepaid:'Pacote adicional pré-pago'};
export const UNIT_KINDS={image:'Imagem final',video:'Vídeo final',conversation:'Atendimento por conversa',publication:'Publicação assistida',consultation:'Consultoria entregue',ad_management:'Gestão de campanha',storage:'Armazenamento em GB',support:'Suporte em horas',other:'Outra entrega especificada'};
export const PLAN_TERMS=[['audience','Para quem é'],['benefit','Benefício e objetivo'],['materials','Materiais aceitos e responsabilidade pelo envio'],['formats','Formatos, duração e qualidade'],['deliveryTime','Prazo e condição de início'],['revisions','Revisões incluídas'],['storage','Armazenamento e retenção dos arquivos'],['support','Suporte e horário de atendimento'],['publication','Publicação incluída ou contratada à parte'],['accounts','Empresas e contas atendidas'],['whatsapp','Uso do WhatsApp e necessidade de ativação'],['overage','Excedentes e autorização antes de cobrar'],['renewal','Periodicidade, renovação e reajuste'],['cancellation','Cancelamento'],['failures','Falhas, refação e reembolso'],['taxNotice','Tributos e valor final ao cliente'],['payment','Condições de pagamento'],['counting','Como as entregas da franquia são contadas']];
export const COST_FIELDS=[['hourlyCents','Custo da hora de trabalho (R$)','money'],['fixedMonthlyCents','Custos fixos mensais a ratear (R$)','money'],['expectedCustomers','Clientes ou pedidos previstos por mês','integer'],['availableHours','Horas disponíveis por mês para esta oferta','number'],['reworkBps','Reserva de retrabalho (%)','percent'],['taxBps','Tributos sobre a receita (%)','percent'],['marginBps','Margem desejada sobre a receita (%)','percent']];
export const CHANNELS={stripe:'Stripe',sicredi:'Boleto manual Sicredi'};
export const BASE_COUNTING='A franquia descreve entregas, não chamadas internas de IA. Falhas sem arquivo válido não são entregas. Revisões incluídas e refações por falha não geram nova cobrança. Um pedido adicional fora do escopo exige orçamento e aceite prévios.';
export function blankPlan(kind='subscription'){return {kind,name:PLAN_KINDS[kind],terms:Object.fromEntries(PLAN_TERMS.map(([k])=>[k,k==='counting'?BASE_COUNTING:''])),lines:[{unit:kind==='publishing'?'publication':kind==='consulting'?'consultation':kind==='ad_management'?'ad_management':'image',quantity:null,specification:'',unitCostCents:null,minutes:null,confidence:'unknown',reference:''}],costs:Object.fromEntries(COST_FIELDS.map(([k])=>[k,null])),costReference:'',observedDate:'',channels:Object.keys(CHANNELS).map(id=>({id,percentBps:null,fixedCents:null,minutes:null,reference:''})),selectedChannel:'stripe',regularPriceCents:null,launchPriceCents:null,launchSlots:null,launchUntil:'',launchConditions:''};}
const known=v=>typeof v==='number'&&Number.isFinite(v)&&v>=0;
const integer=v=>known(v)&&Number.isSafeInteger(v);
const validDate=s=>/^\d{4}-\d{2}-\d{2}$/.test(s||'')&&Number.isFinite(Date.parse(s))&&new Date(s).toISOString().slice(0,10)===s;
const priced=(price,base,percentBps)=>{if(!integer(price)||price<=0)return null;const chargesCents=Math.ceil(price*percentBps/10000),profitCents=price-chargesCents-base;return {priceCents:price,chargesCents,profitCents,marginBps:Math.floor(profitCents*10000/price)};};

// Monetary inputs are integer cents; percentages are basis points. Unknown
// values remain unknown. This is a scenario, never an imported provider bill.
export function calculatePlan(plan,now=Date.now()){
  const issues=[],warnings=[],costs=plan.costs||{},lines=plan.lines||[],channels=plan.channels||[];
  if(!PLAN_KINDS[plan.kind])issues.push('Escolha o tipo da oferta.');
  if(!plan.name?.trim())issues.push('Dê um nome à oferta.');
  for(const[k,label]of PLAN_TERMS)if(!plan.terms?.[k]?.trim())issues.push('Defina: '+label+'.');
  if(!lines.length)issues.push('Inclua pelo menos uma entrega na franquia.');
  let complete=lines.length>0,direct=0,minutes=0;
  lines.forEach((line,i)=>{if(!UNIT_KINDS[line.unit]||!known(line.quantity)||!['storage','support'].includes(line.unit)&&!integer(line.quantity)||line.quantity<=0||!line.specification?.trim()){issues.push('Defina a quantidade e a especificação da entrega '+(i+1)+'.');complete=false;}if(!integer(line.unitCostCents)||!known(line.minutes)){issues.push('Informe custo e tempo da entrega '+(i+1)+'.');complete=false;}if(!['measured','estimate'].includes(line.confidence)||!line.reference?.trim())issues.push('Registre a origem do custo da entrega '+(i+1)+'.');if(line.confidence==='estimate')warnings.push('Entrega '+(i+1)+': custo estimado, ainda precisa de medição real.');if(known(line.quantity)&&integer(line.unitCostCents)&&known(line.minutes)){direct+=line.quantity*line.unitCostCents;minutes+=line.quantity*line.minutes;}});
  for(const[k,label,type]of COST_FIELDS)if(!known(costs[k])||['money','integer','percent'].includes(type)&&!integer(costs[k])){issues.push('Informe: '+label+'.');complete=false;}
  if(!known(costs.expectedCustomers)||costs.expectedCustomers<=0||!known(costs.availableHours)||costs.availableHours<=0){issues.push('Informe previsão de clientes/pedidos e horas disponíveis maiores que zero.');complete=false;}
  if(!plan.costReference?.trim()||!validDate(plan.observedDate)||plan.observedDate>new Date(now).toISOString().slice(0,10))issues.push('Registre a fonte das premissas e a data em que foram conferidas.');
  if(costs.reworkBps>10000||costs.taxBps>=10000||costs.marginBps>=10000){issues.push('Confira os percentuais de retrabalho, tributos e margem.');complete=false;}
  if(!integer(plan.regularPriceCents)||plan.regularPriceCents<=0)issues.push('Informe o preço normal em avaliação.');
  const results=channels.map(c=>{
    const pending=[];if(!integer(c.percentBps)||c.percentBps>=10000||!integer(c.fixedCents)||!known(c.minutes)||!c.reference?.trim())pending.push('Informe tarifas, tempo de conciliação e fonte.');
    const denominator=10000-(c.percentBps??0)-(costs.taxBps??0)-(costs.marginBps??0);
    if(denominator<=0)pending.push('Tarifas, tributos e margem precisam somar menos de 100%.');
    if(!complete||pending.length)return {id:c.id,complete:false,pending};
    const directCents=Math.ceil(direct),humanCents=Math.ceil(minutes*costs.hourlyCents/60),overheadCents=Math.ceil(costs.fixedMonthlyCents/costs.expectedCustomers),reserveCents=Math.ceil((directCents+humanCents)*costs.reworkBps/10000),collectionCents=Math.ceil(c.minutes*costs.hourlyCents/60),baseCents=directCents+humanCents+overheadCents+reserveCents+collectionCents+c.fixedCents;
    if(!Number.isSafeInteger(baseCents)||baseCents>1000000000)return {id:c.id,complete:false,pending:['O custo agregado ultrapassa o limite desta simulação. Confira as unidades.']};
    const minutesPerCustomer=minutes*(1+costs.reworkBps/10000)+c.minutes,capacity=minutesPerCustomer>0?Math.floor(costs.availableHours*60/minutesPerCustomer):null;
    const percentBps=c.percentBps+costs.taxBps,regular=priced(plan.regularPriceCents,baseCents,percentBps),launch=priced(plan.launchPriceCents,baseCents,percentBps);
    // Include cent rounding of fees so the displayed minimum actually reaches
    // the requested margin. The algebraic minimum can fall one cent short.
    let minimumCents=Math.ceil(baseCents*10000/denominator);
    while(minimumCents>0&&priced(minimumCents,baseCents,percentBps).marginBps<costs.marginBps)minimumCents++;
    return {id:c.id,complete:true,directCents,humanCents,overheadCents,reserveCents,collectionCents,paymentFixedCents:c.fixedCents,baseCents,minimumCents,breakEvenCents:Math.ceil(baseCents*10000/(10000-percentBps)),minutesPerCustomer,capacity,regular,launch,forecastProfitCents:regular?regular.profitCents*costs.expectedCustomers:null};
  });
  const selected=results.find(r=>r.id===plan.selectedChannel);
  if(!selected?.complete)issues.push('Complete as premissas do meio de pagamento escolhido.');
  else{if(selected.capacity===null)issues.push('Registre tempo de trabalho para dimensionar a capacidade.');else if(costs.expectedCustomers>selected.capacity)issues.push('A previsão de clientes/pedidos excede a capacidade de atendimento estimada.');if(selected.regular&&selected.regular.priceCents<selected.minimumCents)issues.push('O preço normal está abaixo do necessário para a margem desejada.');}
  if(plan.launchPriceCents!==null&&plan.launchPriceCents!==undefined){if(plan.kind!=='subscription')issues.push('O desconto de primeira mensalidade se aplica ao plano principal.');if(!integer(plan.launchPriceCents)||plan.launchPriceCents<=0||plan.launchPriceCents>=plan.regularPriceCents)issues.push('O preço de lançamento deve ser positivo e menor que o normal.');if(!integer(plan.launchSlots)||plan.launchSlots<1||selected?.capacity!==null&&selected?.capacity!==undefined&&plan.launchSlots>selected.capacity)issues.push('Defina vagas de lançamento compatíveis com a capacidade real.');if(!validDate(plan.launchUntil)||Date.parse(plan.launchUntil+'T23:59:59-03:00')<=now||!plan.launchConditions?.trim())issues.push('Defina validade futura e condições da oferta de lançamento.');if(selected?.launch?.profitCents<0)issues.push('A primeira mensalidade não cobre os custos deste cenário.');else if(selected?.launch&&selected.launch.priceCents<selected.minimumCents)warnings.push('O lançamento cobre os custos, mas tem margem menor que a desejada.');}
  if(plan.kind==='prepaid')issues.push('Pacotes pré-pagos dependem de saldo auditável e conciliação antes da oferta comercial.');
  return {issues:[...new Set(issues)],warnings,ready:issues.length===0,channels:results,selected:selected||null,period:plan.kind==='subscription'?'mensalidade':'pedido',estimated:true};
}

// Only customer-facing terms leave the pricing module for a proposal.
export function proposalFromPlan(plan){const t=plan.terms;return {title:plan.name,priceCents:plan.regularPriceCents,scope:[t.audience,t.benefit,t.accounts].join('\n\n'),deliverables:plan.lines.map(l=>`${l.quantity} × ${UNIT_KINDS[l.unit]} — ${l.specification}`).join('\n')+'\n\n'+t.materials+'\n'+t.formats+'\n\n'+t.counting,schedule:t.deliveryTime,revisions:t.revisions+'\n\n'+t.support+'\n'+t.storage,exclusions:t.publication+'\n'+t.whatsapp+'\n\n'+t.overage+(plan.kind==='ad_management'?'\nA verba de anúncios é separada da remuneração Helpu.':''),payment:t.payment+'\n\n'+t.renewal+'\n'+t.taxNotice+(plan.kind==='subscription'?'\nPreço normal por mês.':''),cancellation:t.cancellation+'\n\n'+t.failures};}
